SELECT
FROM queue_tickets q INNER JOIN visits v ON v.id = q.visit_id INNER JOIN service_types st ON st.id = q.service_type_id WHERE q.health_center_id = #{healthCenterId} AND q.issued_at::date = CURRENT_DATE
AND q.service_type_id = #{serviceTypeId}
AND q.status = #{status}
AND q.status IN ('WAITING', 'CALLED', 'IN_PROGRESS', 'HOLD')
ORDER BY CASE q.status WHEN 'CALLED' THEN 1 WHEN 'IN_PROGRESS' THEN 2 WHEN 'WAITING' THEN 3 WHEN 'HOLD' THEN 4 ELSE 5 END, q.ticket_number

SELECT COUNT(1)::integer
FROM queue_tickets q
WHERE q.health_center_id = #{healthCenterId}
  AND q.issued_at::date = #{targetDate}
  AND q.status IN ('WAITING', 'CALLED', 'HOLD', 'IN_PROGRESS')

mapper.update:
UPDATE queue_tickets q
SET status = 'NO_SHOW',
	updated_at = CURRENT_TIMESTAMP
WHERE q.health_center_id = #{healthCenterId}
  AND q.issued_at::date = #{targetDate}
  AND q.status IN ('WAITING', 'CALLED', 'HOLD', 'IN_PROGRESS')
